import React, { useState, useEffect } from 'react';
import { cn } from '@/utils/index';

interface Party {
  id: string;
  name: string;
  inn?: string;
  type: 'individual' | 'legal';
}

interface PartySelectorProps {
  value?: Party;
  onChange: (party: Party | null) => void;
  onSearch?: (query: string) => Promise<Party[]>;
  placeholder?: string;
  required?: boolean;
  className?: string;
}

export const PartySelector: React.FC<PartySelectorProps> = ({
  value,
  onChange,
  onSearch,
  placeholder = 'Введите ИНН или название',
  required = false,
  className
}) => {
  const [query, setQuery] = useState(value?.name || '');
  const [suggestions, setSuggestions] = useState<Party[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (query.length >= 3 && onSearch) {
      setIsLoading(true);
      onSearch(query)
        .then(setSuggestions)
        .finally(() => setIsLoading(false));
    } else {
      setSuggestions([]);
    }
  }, [query, onSearch]);

  const handleSelect = (party: Party) => {
    setQuery(party.name);
    onChange(party);
    setIsOpen(false);
  };

  const handleClear = () => {
    setQuery('');
    onChange(null);
    setSuggestions([]);
  };

  return (
    <div className={cn('vk-party-selector', className)}>
      <div className="vk-party-selector__input-wrapper">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => setIsOpen(true)}
          placeholder={placeholder}
          required={required}
          className={cn('vk-party-selector__input', value && 'vk-party-selector__input--selected')}
        />
        {value && (
          <button
            type="button"
            onClick={handleClear}
            className="vk-party-selector__clear"
            aria-label="Очистить"
          >
            ×
          </button>
        )}
      </div>

      {isOpen && (suggestions.length > 0 || isLoading) && (
        <div className="vk-party-selector__dropdown">
          {isLoading ? (
            <div className="vk-party-selector__loading">Поиск...</div>
          ) : (
            suggestions.map(party => (
              <div
                key={party.id}
                onClick={() => handleSelect(party)}
                className="vk-party-selector__option"
              >
                <div className="vk-party-selector__option-name">{party.name}</div>
                {party.inn && (
                  <div className="vk-party-selector__option-inn">ИНН: {party.inn}</div>
                )}
                <div className="vk-party-selector__option-type">
                  {party.type === 'legal' ? 'Юридическое лицо' : 'Физическое лицо'}
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};
